{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_ee892a75c1e51db0257cdc4f", "claim_ids": ["claim_4cae026b60f7ead8b5c017d6", "claim_dc90fe23d8bcecbbf24a15d7"], "query_ids": ["q_314"], "claims": [{"claim_id": "claim_4cae026b60f7ead8b5c017d6", "quote": "To offset the parts tariffs paid by an OEM over a two-year transition period, vehicles assembled in the United States between April 3, 2025, and April 30, 2026, may qualify for an import part tariff adjustment offset of 3.75% of the total Manufacturers Suggested Retail Price (MSRP) value.", "url": "https://www.plantemoran.com/explore-our-thinking/insight/2025/05/adjusting-automobile-and-automobile-parts-tariffs-action", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_dc90fe23d8bcecbbf24a15d7", "quote": "The industry will begin paying a 25% tariff on automotive parts as of May 3, 2025.", "url": "https://www.plantemoran.com/explore-our-thinking/insight/2025/05/adjusting-automobile-and-automobile-parts-tariffs-action", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "affected_product": "automotive parts", "duty_rate": "25%", "effective_date": "May 3, 2025"}}]}, {"pair_id": "conflict_1bfe6deebbd61631c503e6a0", "claim_ids": ["claim_08e557ced3646a64c0872dcd", "claim_f22c832c18a6a6ef391a8b40"], "query_ids": ["q_314"], "claims": [{"claim_id": "claim_08e557ced3646a64c0872dcd", "quote": "Section 301: Four-Year Review (50%) Forced labour (12.5%) MFN (7%) | 69.5% | Section 301 four-year review tariff increased to 50% from 1 January 2026.", "url": "https://www.china-briefing.com/news/us-china-tariff-rates-2025", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301: Four-Year Review", "duty_rate": "50%", "effective_date": "1 January 2026"}}, {"claim_id": "claim_f22c832c18a6a6ef391a8b40", "quote": "Electric vehicles – Increased to 100 percent", "url": "https://www.china-briefing.com/news/us-china-tariff-rates-2025", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "Electric vehicles", "duty_rate": "100 percent"}}]}, {"pair_id": "conflict_c078fd67d9087f7ce3c8ef09", "claim_ids": ["claim_a73276c55de1fcb7327a360e", "claim_f375be7bf84463b9427a10e3"], "query_ids": ["q_314"], "claims": [{"claim_id": "claim_a73276c55de1fcb7327a360e", "quote": "The Section 301 China tariffs implemented in 2018-2019 remain in effect, with most tariff rates unchanged since their initial implementation.", "url": "https://www.autocare.org/government-relations/current-issues/tariffs-and-trade/section-301-china-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301 China tariffs", "legal_authority": "Trade Act of 1974", "effective_date": "2018-2019"}}, {"claim_id": "claim_f375be7bf84463b9427a10e3", "quote": "On 26 March 2025, Trump announced a 25 percent tariff on imports of automobiles and automobile parts from all trade partners, effective 3 April 2025. Many vehicles and vehicle parts coming from China were already subject to tariffs of up to 25 percent under Section 301.", "url": "https://www.china-briefing.com/news/us-china-tariff-rates-2025", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "affected_product": "vehicles and vehicle parts", "duty_rate": "up to 25 percent", "announcement_date": "26 March 2025", "effective_date": "3 April 2025"}}]}, {"pair_id": "conflict_7c870efed4130e810f1a1cff", "claim_ids": ["claim_3f13b8da010ef4af85986987", "claim_a0882bd2ad4fa0f4ff69f770"], "query_ids": ["q_315"], "claims": [{"claim_id": "claim_3f13b8da010ef4af85986987", "quote": "December 7, 2016 : CIT: Energizer Battery v. US, Slip Op. 16-116: The CIT holds a simple assembly of flashlights is insufficient for justify a substantial transformation of the goods for Country of Origin purposes.", "url": "https://www.tradelawcounsel.com/country-of-origin", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Energizer Battery"}}, {"claim_id": "claim_a0882bd2ad4fa0f4ff69f770", "quote": "January 23, 2020: CBP: Substantial Transformation: H303864 dated December 26, 2019 and concerning automotive windshield wiper pumps, where Customs rules against a substantial transformation in Mexico using Energizer Battery.", "url": "https://www.tradelawcounsel.com/country-of-origin", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Energizer Battery", "announcement_date": "January 23, 2020"}}]}, {"pair_id": "conflict_763751c7487f8eb745f0842e", "claim_ids": ["claim_54b8195cf9f24eb7468c173d", "claim_ec838f2e0f7dc789c5886acf"], "query_ids": ["q_315"], "claims": [{"claim_id": "claim_54b8195cf9f24eb7468c173d", "quote": "Per CBP rulings including N357277 on control arms, simple assembly operations do not result in substantial transformation. The character remains the country of origin of the inputs that gave the product its essential identity.", "url": "https://gingercontrol.com/blog/country-of-origin-determination-rules", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "control arms"}}, {"claim_id": "claim_ec838f2e0f7dc789c5886acf", "quote": "The 2026 CBP ruling N357277 on control arms confirmed that assembly of components does not result in substantial transformation, and the character of the control arms remained the ball joint assembly's origin.", "url": "https://gingercontrol.com/blog/country-of-origin-determination-rules", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "CBP ruling N357277", "affected_product": "control arms"}}]}, {"pair_id": "conflict_29f1cbffbd2876e85b43644b", "claim_ids": ["claim_876a5bf08daf218cbe115428", "claim_aff7d3a0c5c7c295ed1d03e6"], "query_ids": ["q_316"], "claims": [{"claim_id": "claim_876a5bf08daf218cbe115428", "quote": "Electric vehicle motors are classified under 8501, and EV battery packs fall under 8507.", "url": "https://www.camtomx.com/en/blog/hts-classification-automotive-parts-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "8507"}}, {"claim_id": "claim_aff7d3a0c5c7c295ed1d03e6", "quote": "Electric vehicle motors are classified under 8501, and EV battery packs fall under 8507.", "url": "https://www.camtomx.com/en/blog/hts-classification-automotive-parts-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "8501"}}]}, {"pair_id": "conflict_3b51c7d72c44fde7128a8783", "claim_ids": ["claim_2c459b3e25009d9ef46099bb", "claim_cbe69d9e4ccf199bba99e944"], "query_ids": ["q_317"], "claims": [{"claim_id": "claim_2c459b3e25009d9ef46099bb", "quote": "Tariffs on EVs under Section 301 will rise from 25% to 100% in 2024.", "url": "https://mobilitynotes.com/summary-of-ev-related-u-s-tariffs-on-chinese-imports", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "affected_product": "EVs", "duty_rate": "100%", "effective_date": "2024"}}, {"claim_id": "claim_cbe69d9e4ccf199bba99e944", "quote": "in May 2024, the Biden administration imposed a 100% additional tariff on Chinese EV imports. Subsequently, the Trump administration raised this tariff substantially to 145%-245%, before negotiations reduced it to 135%.", "url": "https://www.nature.com/articles/s44168-025-00330-6", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "100% additional tariff", "legal_authority": "Biden administration", "announcement_date": "May 2024"}}]}, {"pair_id": "conflict_25ad480ce849a85f6590a0f2", "claim_ids": ["claim_30c63ef11da3430bb246822d", "claim_e1578b8044f522c2f4142bd1"], "query_ids": ["q_317"], "claims": [{"claim_id": "claim_30c63ef11da3430bb246822d", "quote": "On May 14, the Biden administration announced the US will impose additional tariffs on $18 billion worth of goods from China, which includes a tariff increase from 25% to 100% on electric vehicles (EVs), and from 7.5% to 25% on lithium-ion (li-ion) batteries for electric vehicles in 2024.", "url": "https://interactanalysis.com/insight/us-tariff-increases-what-is-the-impact-on-the-us-and-china-markets-for-electric-vehicles-and-li-ion-batteries", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"announcement_date": "May 14"}}, {"claim_id": "claim_e1578b8044f522c2f4142bd1", "quote": "Tariffs on lithium-ion EV batteries will rise from 7.5% to 25% in 2024", "url": "https://mobilitynotes.com/summary-of-ev-related-u-s-tariffs-on-chinese-imports", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "affected_product": "lithium-ion EV batteries", "duty_rate": "25%", "effective_date": "2024"}}]}, {"pair_id": "conflict_a95c204184e85e3f5c12d0e3", "claim_ids": ["claim_0bc99aa701ad093c811b7990", "claim_44407dfa3f06d5487c3e9902"], "query_ids": ["q_318"], "claims": [{"claim_id": "claim_0bc99aa701ad093c811b7990", "quote": "In the second scenario, since both the stator core and the rotor core are produced in Korea, the country origin of the stator-rotor assembly will be Korea.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=H313371", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "Korea"}}, {"claim_id": "claim_44407dfa3f06d5487c3e9902", "quote": "Accordingly, we find that in Scenario 1, for purposes of determining the applicability of 301 trade remedy dutes, since both the rotor core and stator core are of Chinese origin, the country of origin of the stator-rotor assembly will be China.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=H313371", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_357ad1eba99a4aae892c3ece", "claim_ids": ["claim_40225326ec85c253be9635d8", "claim_a81b542b05fc740703092afe"], "query_ids": ["q_319"], "claims": [{"claim_id": "claim_40225326ec85c253be9635d8", "quote": "EV parts include HS tariff lines 8507.60 (lithium -ion bateries), 8507.90 (batery parts), and 8501.32 (electric motors).", "url": "https://www.usitc.gov/publications/332/working_papers/ev_paper_05072024_ec_working_paper_series.pdf", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {}}, {"claim_id": "claim_a81b542b05fc740703092afe", "quote": "Pursuant to U.S. Note 20 to Subchapter III, Chapter 99, HTSUS, products of China classified under subheading 8501.53.40, HTSUS, unless specifically excluded, are subject to an additional 25 percent ad valorem rate of duty.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H329719&highlight=8501.53%2A", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "U.S. Note 20 to Subchapter III, Chapter 99, HTSUS", "country_of_origin": "China", "duty_rate": "25 percent ad valorem"}}]}]}

